INSERT INTO catalog (id,data) SELECT 'wholesale-ttk26','{"id":"wholesale-ttk26","serviceCode":"TTK26","title":"Winter White Snow ตุรเคีย อิสตันบูล ปามุคคาเล คัปปาโดเกีย เออร์ซีเยส","category":"ทัวร์","country":"ตุรเคีย","price":46888,"duration":"9 วัน 7 คืน","tag":"ทัวร์ฤดูหนาว","published":false,"description":"บินตรง Turkish Airlines เที่ยวตุรเคียเส้นทางอิสตันบูล–ชานัคคาเล–ปามุคคาเล–คอนย่า–คัปปาโดเกีย–ไคเซรี–อังการ่า เยือนปราสาทปุยฝ้าย ชมกระเช้าเขาเออร์ซีเยส พักโรงแรมสไตล์ถ้ำ 1 คืน ชิมไอศกรีม MADO และล่องเรือ Private ช่องแคบบอสฟอรัส โปรแกรม 9 วัน 7 คืน รวมอาหารตามรายการ 18 มื้อ กิจกรรมบอลลูนและสกีบางส่วนมีค่าใช้จ่ายเพิ่มเติม สภาพหิมะและกิจกรรมขึ้นอยู่กับอากาศ","image":"/api/media/db47e09c-d25c-40b2-8e67-1a6f30598dc8.jpg","gallery":["/api/media/302276d3-8449-45ce-8052-7b9fb0357b37.jpg","/api/media/4784f619-1456-4443-b248-f61189e47c8d.jpg","/api/media/881fa3e1-1e5e-445d-b6ca-f198fffc9231.jpg","/api/media/4e152d7d-771b-4869-a6cd-42b9d3ca23a1.jpg","/api/media/cf7ffa3a-cffe-4bfa-8827-06797197144e.jpg"],"activityTags":["หิมะ","ฤดูหนาว","กระเช้า","สกี","ธรรมชาติ","เมืองเก่า","มรดกโลก","ล่องเรือ","ช้อปปิ้ง","โรงแรมถ้ำ","ปามุคคาเล","คัปปาโดเกีย","อิสตันบูล","บอลลูน (กิจกรรมเสริม)"],"airline":"Turkish Airlines (TK) — บินตรง กรุงเทพฯ–อิสตันบูล","hotel":"โรงแรมตามรายการ 7 คืน รวมโรงแรมสไตล์ถ้ำ 1 คืน (หรือระดับใกล้เคียง; ไม่ระบุระดับดาว)","highlights":["บินตรง Turkish Airlines พร้อมสัมภาระโหลด 30 กก. / ถือขึ้นเครื่อง 7 กก.","นั่งกระเช้าชมเขาเออร์ซีเยสและบรรยากาศสกีรีสอร์ท (ขึ้นกับอากาศ; อุปกรณ์และกิจกรรมสกีไม่รวม)","ปามุคคาเล ปราสาทปุยฝ้ายและเมืองโบราณเฮียราโพลิส","เที่ยวคัปปาโดเกีย นครใต้ดินชาดัค ยูชิซาร์ หุบเขานกพิราบ/แห่งรัก/เกอเรเม","พักโรงแรมสไตล์ถ้ำ 1 คืนและชิมไอศกรีม MADO","ล่องเรือ Private ช่องแคบบอสฟอรัส รวมตามโปรแกรม","ถ่ายภาพทอปกาปี ฮาเกียโซเฟีย สุเหร่าสีน้ำเงิน ม้าไม้ทรอย สุสานอตาเติร์ก และหอคอยกาลาตา","ช้อปปิ้งแกรนด์บาซาร์ ตลาดเครื่องเทศ ทักซิม Galataport และเดินย่าน Balat","บอลลูน / Jeep Safari / Classic car เป็นกิจกรรมเสริม ไม่รวมในราคา"],"itinerary":[{"title":"กรุงเทพฯ — อิสตันบูล","description":"06:00 น. พบกันที่สนามบินสุวรรณภูมิ อาคารผู้โดยสารระหว่างประเทศขาออก ชั้น 4 เคาน์เตอร์ Turkish Airlines พร้อมเจ้าหน้าที่อำนวยความสะดวก\n10:10 น. บินตรง TK065 BKK–IST ถึงอิสตันบูล 16:45 น. ผ่านตรวจคนเข้าเมืองและศุลกากร เดินทางเข้าเมือง ปรับเวลาท้องถิ่นช้ากว่าไทย 4 ชั่วโมง","meals":"เย็น (มื้อที่ 1); บนเครื่องตามบริการสายการบิน","hotel":"GOLDEN WAY HOTEL หรือระดับใกล้เคียง"},{"title":"อิสตันบูล — ทอปกาปี — ฮาเกียโซเฟีย — สุเหร่าสีน้ำเงิน — ชานัคคาเล","description":"ถ่ายภาพด้านนอกพระราชวังทอปกาปีและสุเหร่าเซนต์โซเฟีย (Hagia Sophia) ไม่รวมค่าบัตรเข้าชมทั้งสองแห่ง\nเช็กอินสุเหร่าสีน้ำเงินและฮิปโปโดม หากเข้าชมภายในต้องแต่งกายสุภาพ สุภาพสตรีเตรียมผ้าคลุมศีรษะ; อาจปรับชมด้านนอกหากมีพิธีกรรม ปิดซ่อม หรือข้อจำกัดหน้างาน\nเดินตลาดแกรนด์บาซาร์ เลือกสินค้าพื้นเมืองและของที่ระลึก ก่อนเดินทางสู่ชานัคคาเล","meals":"เช้า / กลางวัน / เย็น (มื้อที่ 2–4)","hotel":"IRIS HOTEL หรือระดับใกล้เคียง"},{"title":"ชานัคคาเล — ม้าไม้ทรอย — ปามุคคาเล — เฮียราโพลิส — ปราสาทปุยฝ้าย","description":"ถ่ายภาพม้าไม้ทรอยในชานัคคาเล เดินทางสู่ปามุคคาเล เยือนเมืองโบราณเฮียราโพลิส ชมโบราณสถานและปราสาทปุยฝ้าย (Cotton Castle) ลานหินปูนสีขาวเกิดจากการตกตะกอนน้ำแร่ ไม่ใช่หิมะ\nพักโรงแรมในปามุคคาเลตามรายการ","meals":"เช้า / กลางวัน / เย็น (มื้อที่ 5–7)","hotel":"POLAT THERMAL หรือระดับใกล้เคียง"},{"title":"ปามุคคาเล — คอนย่า — สุลต่านฮานี — เมฟลานา — คัปปาโดเกีย","description":"เดินทางสู่คอนย่า ถ่ายภาพประตูหินอ่อนด้านหน้าสุลต่านฮานี (Sultan Han Caravanserai) ที่พักกองคาราวานในอดีต และถ่ายภาพด้านนอกพิพิธภัณฑ์เมฟลานา\nเดินทางต่อสู่คัปปาโดเกีย ชมภูมิประเทศหินทูฟา พักโรงแรมสไตล์ถ้ำ 1 คืนตามโปรแกรม โรงแรมจริงยืนยันอีกครั้ง","meals":"เช้า / กลางวัน / เย็น (มื้อที่ 8–10)","hotel":"CHARM OF CAPPADOCIA โรงแรมสไตล์ถ้ำ หรือระดับใกล้เคียง"},{"title":"คัปปาโดเกีย — นครใต้ดินชาดัค — ยูชิซาร์ — หุบเขาต่าง ๆ — อวานอส","description":"กิจกรรมเสริมช่วงเช้า (ไม่รวมราคา): บอลลูนชมคัปปาโดเกีย ประมาณ 300 USD/ท่าน ใช้เวลาบินประมาณ 1 ชั่วโมง รับจากโรงแรมราว 04:00–05:00 น. หรือ Jeep Safari ประมาณ 120 USD/ท่าน 20 นาที ขั้นต่ำ 8 ท่าน/กรุ๊ป หรือ Classic car ประมาณ 200 USD ขั้นต่ำ 8 ท่าน/กรุ๊ป (หน่วยราคา Classic car รอยืนยัน) ราคาทุกกิจกรรมต้องยืนยันกับผู้จัด ซื้อผ่านบริษัทหรือหัวหน้าทัวร์เท่านั้น บอลลูนขึ้นกับอากาศและความปลอดภัย\nชมโรงงานทอพรม โรงงานเซรามิก ร้านจิวเวลรี นครใต้ดินชาดัค ปราสาทหินยูชิซาร์ หุบเขานกพิราบ หุบเขาแห่งรัก และหุบเขาเกอเรเม\nชมหมู่บ้านอวานอสและชิมไอศกรีม MADO ตามโปรแกรม","meals":"เช้า / กลางวัน / เย็น (มื้อที่ 11–13)","hotel":"EMIN KOCAK HOTEL หรือระดับใกล้เคียง"},{"title":"คัปปาโดเกีย — ไคเซรี — เขาเออร์ซีเยส — ทะเลสาบเกลือ — อังการ่า","description":"เดินทางผ่านเมืองไคเซรี นั่งกระเช้าขึ้นสกีรีสอร์ทบนเขาเออร์ซีเยส (Erciyes Mountain) ชมวิวและถ่ายภาพหิมะ อิสระกิจกรรมสกีตามอัธยาศัย ไม่รวมค่าอุปกรณ์และกิจกรรมสกี\nการเข้าถึงรีสอร์ท กระเช้า และสภาพหิมะขึ้นกับอากาศ ผู้จัดอาจปรับรายการหากอากาศไม่เอื้ออำนวย\nเดินทางต่ออังการ่า แวะชมทะเลสาบเกลือ Tuz ลักษณะน้ำและสีของทะเลสาบเปลี่ยนตามฤดูกาล","meals":"เช้า / กลางวัน / เย็น (มื้อที่ 14–16)","hotel":"CONNECT HOTEL หรือระดับใกล้เคียง"},{"title":"อังการ่า — สุสานอตาเติร์ก — อิสตันบูล — ล่องเรือบอสฟอรัส — ทักซิม","description":"เยือนสุสานอตาเติร์ก (Anıtkabir) แล้วเดินทางสู่อิสตันบูล แวะโรงงานเครื่องหนัง\nล่องเรือ Private ชมช่องแคบบอสฟอรัสระหว่างยุโรปและเอเชีย รวมค่าล่องเรือตามโปรแกรม\nแวะ Candy Shop/ร้าน Turkish Delight เลือกของฝาก เดินตลาดเครื่องเทศและจัตุรัสทักซิมสแควร์ ชมบรรยากาศย่านรถรางสีแดง\nอิสระอาหารกลางวันและเย็น ไม่รวมในราคา","meals":"เช้า (มื้อที่ 17); กลางวันและเย็นอิสระ","hotel":"GOLDEN WAY HOTEL หรือระดับใกล้เคียง"},{"title":"Balat — Galataport — หอคอยกาลาตา — อิสตันบูล — เดินทางกลับ","description":"เดินย่านบ้านสีสัน Balat ช้อปปิ้งและชมบรรยากาศ Galataport แวะถ่ายภาพด้านนอกหอคอยกาลาตา\nอิสระอาหารกลางวัน เดินทางสู่สนามบินอิสตันบูล\nรอบ 26 พ.ย.–4 ธ.ค. และ 10–18 ธ.ค.: TK064 IST–BKK 19:45–08:40 ถึงไทยวันถัดไป\nรอบ 3–11 ธ.ค.: TK058 IST–BKK 15:25–04:15 ถึงไทยวันถัดไป อาจปรับเวลาท่องเที่ยววันสุดท้ายตามเที่ยวบิน","meals":"เช้า (มื้อที่ 18); กลางวันอิสระ; บนเครื่องตามบริการสายการบิน","hotel":"พักบนเครื่องบิน"},{"title":"เดินทางถึงกรุงเทพฯ","description":"ถึงสนามบินสุวรรณภูมิโดยสวัสดิภาพ เวลา 08:40 น. สำหรับ TK064 หรือ 04:15 น. สำหรับ TK058 ในรอบ 3–11 ธ.ค.\nเวลาเที่ยวบินและลำดับรายการอาจเปลี่ยนแปลง ให้ตรวจใบนัดหมายฉบับยืนยันก่อนเดินทาง","meals":"ตามบริการสายการบิน (PDF ไม่ระบุมื้อ)","hotel":"ไม่มีที่พัก — สิ้นสุดการเดินทาง"}],"departures":[{"start":"2026-11-26","end":"2026-12-04","price":46888,"capacity":25,"seats":null,"commission":null,"outboundFlight":"TK065 BKK–IST 10:10–16:45","returnFlight":"TK064 IST–BKK 19:45–08:40 (+1 วัน)"},{"start":"2026-12-03","end":"2026-12-11","price":46888,"capacity":25,"seats":null,"commission":null,"outboundFlight":"TK065 BKK–IST 10:10–16:45","returnFlight":"TK058 IST–BKK 15:25–04:15 (+1 วัน)"},{"start":"2026-12-10","end":"2026-12-18","price":46888,"capacity":25,"seats":null,"commission":null,"outboundFlight":"TK065 BKK–IST 10:10–16:45","returnFlight":"TK064 IST–BKK 19:45–08:40 (+1 วัน)"}],"included":["ตั๋วเครื่องบินไป–กลับชั้นประหยัด Turkish Airlines พร้อมภาษีสนามบินตามรายการ","โรงแรม 7 คืน ห้องละ 2–3 ท่าน ตามรายการหรือระดับใกล้เคียง รวมโรงแรมสไตล์ถ้ำ 1 คืน","อาหารตามรายการ 18 มื้อ (อาหารบนเครื่องตามบริการสายการบิน)","ค่าเข้าชมและยานพาหนะตามรายการ รวมกระเช้าเขาเออร์ซีเยสและล่องเรือ Private บอสฟอรัสตามโปรแกรม","เจ้าหน้าที่อำนวยความสะดวกและหัวหน้าทัวร์คนไทย","สัมภาระโหลด 30 กก. ถือขึ้นเครื่อง 7 กก. ต่อท่าน ตามเงื่อนไขสายการบิน","ประกันอุบัติเหตุวงเงิน 1,000,000 บาทและค่ารักษาตามเงื่อนไขกรมธรรม์","ต้นฉบับระบุรวม VAT 7% และหัก ณ ที่จ่าย 3% เฉพาะค่าบริการ — ต้องยืนยันกับข้อความไม่รวมภาษีหน้า 23"],"excluded":["ค่าพาสปอร์ตและเอกสารต่างด้าว/เอกสารเดินทางส่วนตัว","อาหารมื้ออิสระ ค่าเครื่องดื่ม ซักรีด โทรศัพท์ และค่าใช้จ่ายส่วนตัวนอกโปรแกรม","ค่าภาษีเดินทาง (ถ้ามี) ภาษีบางรายการ และภาษีน้ำมัน/สนามบินที่ปรับเพิ่มหลังออกตั๋ว ต้องยืนยันก่อนจอง","ค่าพนักงานยกกระเป๋าและสัมภาระเกินน้ำหนัก","ทิปไกด์และคนขับ 64 USD/ท่าน + หัวหน้าทัวร์ 1,000 บาท/ท่าน","บอลลูนประมาณ 300 USD/ท่าน; Jeep Safari ประมาณ 120 USD/ท่าน; Classic car ประมาณ 200 USD (หน่วยราคา Classic car รอยืนยัน)","ค่าอุปกรณ์สกีและกิจกรรมสกีอื่น ๆ","ค่าบัตรเข้าพระราชวังทอปกาปีและฮาเกียโซเฟีย (โปรแกรมถ่ายภาพด้านนอก)","พักเดี่ยว/เดินทางคนเดียวเพิ่ม 12,500 บาท; ทารกไม่เกิน 2 ปี 14,500 บาท","ประกันสุขภาพและค่าใช้จ่ายที่ไม่อยู่ในกรมธรรม์"],"terms":"การจองและชำระเงิน\nมัดจำ 25,000 บาท/ท่าน พร้อมสำเนาหน้าพาสปอร์ตและหลักฐานชำระเงิน ชำระส่วนที่เหลือก่อนเดินทาง 20–25 วัน หรือภายในกำหนดผู้จัดหากต้องออกตั๋วก่อน\nขั้นต่ำออกกรุ๊ป 15 ท่าน หากไม่ครบอาจส่งจอยน์ทัวร์ เลื่อน ยกเลิก หรือปรับราคา โดยต้นฉบับระบุแจ้งก่อนเดินทาง 15 วัน ห้ามออกตั๋วต่อภายในประเทศก่อนติดต่อผู้จัด\n\nเอกสารเดินทาง\nพาสปอร์ตต้องเหลืออายุมากกว่า 6 เดือนนับจากวันเดินทางไป–กลับ และมีหน้าว่างอย่างน้อย 3 หน้า ส่งพร้อมหลักฐานมัดจำ ต้นฉบับระบุผู้ถือพาสปอร์ตไทยไม่ต้องขอวีซ่า แต่ต้องตรวจข้อกำหนดล่าสุดก่อนขาย/เดินทาง สัญชาติอื่นสอบถามผู้จัด\n\nราคาและห้องพัก\nผู้ใหญ่ 46,888 บาท/ท่าน ไม่มีราคาเด็ก 2–11 ปีแยกในต้นฉบับ ให้ยืนยันราคาก่อนจอง; ทารกไม่เกิน 2 ปี 14,500 บาท; พักเดี่ยวหรือเดินทางคนเดียวเพิ่ม 12,500 บาท\nผู้มีตั๋วเครื่องบินแล้วหักราคาทัวร์ 15,000 บาทตามต้นฉบับ ต้องยืนยันเงื่อนไขที่นั่งและเส้นทางก่อนจอง\nหน้า 3 เสนออัปเกรด Business Class เพิ่ม 110,000–120,000 บาท แต่หน้า 22 ระบุตั๋วกรุ๊ปไม่สามารถอัปเกรดได้ ต้องยืนยันความขัดแย้งนี้กับผู้จัดก่อนเสนอขาย\nตั๋วกรุ๊ปต้องเดินทางไป–กลับพร้อมคณะ เปลี่ยนวันไม่ได้ การแยกวันเดินทางต้องสอบถามราคาใหม่ สายการบินเป็นผู้จัดที่นั่ง\nโรงแรมที่พักแจ้งพร้อมใบนัดหมายก่อนเดินทาง 5–7 วัน อาจเปลี่ยนเป็นระดับใกล้เคียง/เมืองใกล้เคียงเมื่อมีเทศกาล ห้องพัก 2–3 ท่าน; ห้อง Triple อาจเป็นเตียงเสริม/โซฟาเบดหรือไม่มี หากต้องแยก Twin+Single ต้องจ่ายพักเดี่ยวเพิ่ม ห้องต่างประเภทอาจไม่ติดกัน ต่างชั้น หรือขนาดต่างกัน\n\nกิจกรรมและค่าใช้จ่ายเพิ่มเติม\nบอลลูนประมาณ 300 USD/ท่าน ไม่รวมราคา; Jeep Safari ประมาณ 120 USD/ท่าน 20 นาที ขั้นต่ำ 8 ท่าน/กรุ๊ป; Classic car ประมาณ 200 USD ขั้นต่ำ 8 ท่าน/กรุ๊ป (ต้นฉบับไม่ระบุชัดว่าต่อท่านหรือต่อคัน) ซื้อกับบริษัท/หัวหน้าทัวร์เท่านั้น ราคาอาจเปลี่ยน\nกระเช้า/สกีรีสอร์ท/บอลลูนและหิมะขึ้นกับสภาพอากาศ ไม่รับประกันหิมะหรือการบินบอลลูน ไม่รวมอุปกรณ์และกิจกรรมสกี\nทิปไกด์และคนขับ 64 USD/ท่าน และหัวหน้าทัวร์ 1,000 บาท/ท่าน ไม่รวมในราคา หิมะและใบไม้เปลี่ยนสีเร็วช้าตามสภาพอากาศ\n\nการยกเลิกตามต้นฉบับ (ต้องยืนยันก่อนรับจอง)\n45 วันขึ้นไป: คืนเงินหลังหักค่าใช้จ่ายเกิดขึ้นจริง เช่น ตั๋ว/โรงแรม\n25–45 วัน: คืนมัดจำ 50% และหักค่าใช้จ่ายเกิดขึ้นจริง ช่วง 45 วันซ้ำกับข้อความข้อก่อน ต้องยืนยันผู้จัด\nน้อยกว่า 25 วัน: เรียกเก็บเต็มราคาทัวร์\nวันหยุดเทศกาล/นักขัตฤกษ์/วันหยุดยาว: ต้นฉบับระบุเก็บค่าทัวร์ทั้งหมดเมื่อยกเลิก\nเจ็บป่วยจนเดินทางไม่ได้ต้องมีใบรับรองแพทย์ ผู้จัดเรียกเก็บค่าใช้จ่ายจริง; ถูกปฏิเสธเข้า–ออกประเทศ/เอกสารไม่ถูกต้อง/สละบริการหรือแยกจากคณะไม่คืนค่าใช้จ่ายตามต้นฉบับ\n\nประกันและข้อจำกัด\nประกันอุบัติเหตุวงเงิน 1,000,000 บาท ค่ารักษาตามเงื่อนไขกรมธรรม์ ต้องมีใบเสร็จและเอกสารแพทย์ ไม่คุ้มครองโรคประจำตัว ทรัพย์สินส่วนตัว หรือประกันสุขภาพ ซื้อประกันสุขภาพเพิ่มได้\nโปรแกรมและเที่ยวบินอาจเปลี่ยนตามอากาศ สถานที่ เทศกาล ความปลอดภัย และสถานการณ์ท้องถิ่น ผู้จัดไม่รับผิดเหตุอยู่นอกการควบคุม เช่น สายการบินล่าช้า/ยกเลิก นัดหยุดงาน จลาจล ภัยธรรมชาติ หรือการนำสิ่งผิดกฎหมาย\nผู้ต้องการความช่วยเหลือพิเศษ/รถเข็นแจ้งอย่างน้อย 14 วันก่อนเดินทาง การจัดห้องพักขึ้นกับโรงแรม คำรับรองของไกด์/ตัวแทนต้องมีเอกสารจากผู้มีอำนาจ\nรายการเป็นข้อเสนอจนผู้จัดยืนยันโรงแรมและบริการ ชำระเงินถือว่ายอมรับเงื่อนไขตามเอกสารต้นฉบับ โปรดอ่านเงื่อนไขฉบับเต็มและให้ผู้จัดยืนยันก่อนเปิดขาย\n\nภาพประกอบ\nภาพหน้าปกและแกลเลอรีสร้างด้วย AI ไม่ใช่ภาพถ่ายจากรอบเดินทางจริง สภาพสถานที่ หิมะ และกิจกรรมจริงอาจแตกต่าง\n","wholesale":{"supplier":"ITRAVEL (อ้างอิงโฟลเดอร์ผู้จัด — รอยืนยัน)","sourceFile":"TTK26 Winter White Snow Türkiye อิสตัลบูล ปามุคคาเล คัปปาโดเกีย ERCIYES MOUNTAIN SKI.pdf","importedAt":"2026-10-07","notes":["นำเข้าเพื่อทดลองเป็นฉบับร่าง ยังไม่เปิดขาย; supplier ITRAVEL อ้างอิงจากโฟลเดอร์ผู้จัด ต้องยืนยันชื่อผู้จัด","ตารางระบุ 25 ที่นั่งต่อรอบเป็นจำนวนรับได้ ไม่ใช่ที่นั่งคงเหลือปัจจุบัน; ที่นั่งคงเหลือและค่าคอมมิชชันรอยืนยัน","หน้า 3 เสนอ Business Class เพิ่ม 110,000–120,000 บาท แต่หน้า 22 ระบุว่าตั๋วกรุ๊ปอัปเกรดไม่ได้ ต้องยืนยันก่อนเสนอขาย","หน้า 22 ระบุรวม VAT 7% 